@page "/settings"
@rendermode InteractiveServer
@using sv_09f7bf0fc8e24ee78c30cc552c74f11e.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <h4 class="sidebar-title">Settings</h4>
        <ul class="nav flex-column">
            @foreach (var section in _sections)
            {
                <li class="nav-item">
                    <button class="nav-link @(ActiveSection == section ? "active" : "")"
                            @onclick="() => ActiveSection = section">
                        @section
                    </button>
                </li>
            }
        </ul>
    </nav>

    <main class="settings-content">
        @if (ActiveSection == "Profile")
        {
            <section class="settings-section">
                <h3>Profile</h3>
                @if (_profile is not null)
                {
                    <div class="avatar-preview mb-3">
                        <img src="@_editProfile!.AvatarUrl" alt="Avatar" class="avatar-img" />
                        <small class="text-muted d-block mt-1">@_editProfile.AvatarUrl</small>
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Display Name</label>
                        <input type="text" class="form-control" @bind="_editProfile.DisplayName" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Email</label>
                        <input type="email" class="form-control" @bind="_editProfile.Email" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Bio</label>
                        <textarea class="form-control" rows="4" @bind="_editProfile.Bio"></textarea>
                    </div>
                    <div class="d-flex gap-2">
                        <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                        <button class="btn btn-outline-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
                    </div>
                    @if (_profileSaveMessage is not null)
                    {
                        <div class="alert alert-success mt-3" role="alert">@_profileSaveMessage</div>
                    }
                }
            </section>
        }
        else if (ActiveSection == "Notifications")
        {
            <section class="settings-section">
                <h3>Notifications</h3>
                @if (_notificationPrefs is not null)
                {
                    <div class="form-check form-switch mb-3">
                        <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_editNotifications!.EmailNotifications" />
                        <label class="form-check-label" for="emailNotif">Email Notifications</label>
                    </div>
                    <div class="form-check form-switch mb-3">
                        <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_editNotifications.PushNotifications" />
                        <label class="form-check-label" for="pushNotif">Push Notifications</label>
                    </div>
                    <div class="form-check form-switch mb-3">
                        <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_editNotifications.WeeklyDigest" />
                        <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
                    </div>

                    <h5 class="mt-4">Muted Channels</h5>
                    @for (int i = 0; i < _editNotifications.MutedChannels.Count; i++)
                    {
                        var index = i;
                        <div class="form-check mb-2">
                            <input class="form-check-input" type="checkbox" id="@($"channel-{index}")"
                                   checked="@_mutedChannelStates[index]"
                                   @onchange="e => ToggleMutedChannel(index, (bool)e.Value!)" />
                            <label class="form-check-label" for="@($"channel-{index}")">@_editNotifications.MutedChannels[index]</label>
                        </div>
                    }

                    <button class="btn btn-primary mt-3" @onclick="SaveNotifications">Save Preferences</button>
                    @if (_notificationSaveMessage is not null)
                    {
                        <div class="alert alert-success mt-3" role="alert">@_notificationSaveMessage</div>
                    }
                }
            </section>
        }
        else if (ActiveSection == "Security")
        {
            <section class="settings-section">
                <h3>Security</h3>
                @if (_securitySettings is not null)
                {
                    <div class="card mb-4">
                        <div class="card-header d-flex justify-content-between align-items-center"
                             style="cursor: pointer" @onclick="() => _passwordPanelExpanded = !_passwordPanelExpanded">
                            <span>Change Password</span>
                            <span>@(_passwordPanelExpanded ? "▲" : "▼")</span>
                        </div>
                        @if (_passwordPanelExpanded)
                        {
                            <div class="card-body">
                                <div class="mb-3">
                                    <label class="form-label">Current Password</label>
                                    <input type="password" class="form-control" @bind="_currentPassword" />
                                </div>
                                <div class="mb-3">
                                    <label class="form-label">New Password</label>
                                    <input type="password" class="form-control" @bind="_newPassword" />
                                </div>
                                <div class="mb-3">
                                    <label class="form-label">Confirm Password</label>
                                    <input type="password" class="form-control" @bind="_confirmPassword" />
                                </div>
                                <button class="btn btn-warning" @onclick="UpdatePassword">Update Password</button>
                                @if (_passwordMessage is not null)
                                {
                                    <div class="alert @(_passwordMessageIsError ? "alert-danger" : "alert-success") mt-3">@_passwordMessage</div>
                                }
                            </div>
                        }
                    </div>

                    <div class="mb-4">
                        <h5>Two-Factor Authentication</h5>
                        <div class="d-flex align-items-center gap-3">
                            <div class="form-check form-switch">
                                <input class="form-check-input" type="checkbox" id="twoFactor" @bind="_twoFactorEnabled" />
                                <label class="form-check-label" for="twoFactor">Enable 2FA</label>
                            </div>
                            <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                                @(_twoFactorEnabled ? "Enabled" : "Disabled")
                            </span>
                        </div>
                        @if (_securitySettings.LastPasswordChange.HasValue)
                        {
                            <small class="text-muted d-block mt-2">Last password change: @_securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</small>
                        }
                    </div>

                    <div class="mb-4">
                        <h5>Active Sessions</h5>
                        <div class="table-responsive">
                            <table class="table table-striped">
                                <thead>
                                    <tr>
                                        <th>Device</th>
                                        <th>Location</th>
                                        <th>Last Active</th>
                                        <th>Action</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    @foreach (var session in _securitySettings.Sessions)
                                    {
                                        <tr>
                                            <td>@session.Device</td>
                                            <td>@session.Location</td>
                                            <td>@session.LastActive.ToString("g")</td>
                                            <td>
                                                @if (session.Id != _currentSessionId)
                                                {
                                                    <button class="btn btn-sm btn-outline-danger"
                                                            @onclick="() => PromptRevokeSession(session)">Revoke</button>
                                                }
                                                else
                                                {
                                                    <span class="badge bg-info">Current</span>
                                                }
                                            </td>
                                        </tr>
                                    }
                                </tbody>
                            </table>
                        </div>
                    </div>

                    @if (_sessionToRevoke is not null)
                    {
                        <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
                            <div class="modal-dialog">
                                <div class="modal-content">
                                    <div class="modal-header">
                                        <h5 class="modal-title">Confirm Revoke Session</h5>
                                        <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                                    </div>
                                    <div class="modal-body">
                                        <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                                    </div>
                                    <div class="modal-footer">
                                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                                        <button class="btn btn-danger" @onclick="ConfirmRevoke">Revoke</button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    }
                }
            </section>
        }
        else if (ActiveSection == "Appearance")
        {
            <section class="settings-section">
                <h3>Appearance</h3>
                @if (_appearance is not null)
                {
                    <div class="mb-4">
                        <h5>Theme</h5>
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                                       value="@theme" checked="@(_editAppearance!.Theme == theme)"
                                       @onchange="() => _editAppearance!.Theme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>

                    <div class="mb-4">
                        <h5>Font Size</h5>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="fontSize" id="@($"size-{size}")"
                                       value="@size" checked="@(_editAppearance!.FontSize == size)"
                                       @onchange="() => _editAppearance!.FontSize = size" />
                                <label class="form-check-label" for="@($"size-{size}")">@size</label>
                            </div>
                        }
                    </div>

                    <div class="mb-4">
                        <h5>Language</h5>
                        <select class="form-select" @bind="_editAppearance!.Language">
                            <option value="English">English</option>
                            <option value="Spanish">Spanish</option>
                            <option value="French">French</option>
                            <option value="German">German</option>
                            <option value="Japanese">Japanese</option>
                        </select>
                    </div>

                    <div class="form-check form-switch mb-4">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="_editAppearance.CompactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>

                    <div class="mb-4">
                        <h5>Preview</h5>
                        <div class="appearance-preview @GetPreviewClasses()">
                            <div class="preview-header">Sample Header</div>
                            <p class="preview-text">This is how your content will look with the selected settings.</p>
                            <button class="preview-button">Sample Button</button>
                        </div>
                    </div>

                    <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
                    @if (_appearanceSaveMessage is not null)
                    {
                        <div class="alert alert-success mt-3" role="alert">@_appearanceSaveMessage</div>
                    }
                }
            </section>
        }
    </main>
</div>

