@code {
    private readonly string[] _sections = { "Profile", "Notifications", "Security", "Appearance" };
    private string ActiveSection { get; set; } = "Profile";

    // Profile
    private UserProfile? _profile;
    private ProfileEdit? _editProfile;
    private string? _profileSaveMessage;

    // Notifications
    private NotificationPrefs? _notificationPrefs;
    private NotificationEdit? _editNotifications;
    private List<bool> _mutedChannelStates = new();
    private string? _notificationSaveMessage;

    // Security
    private SecuritySettings? _securitySettings;
    private bool _passwordPanelExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordMessage;
    private bool _passwordMessageIsError;
    private bool _twoFactorEnabled;
    private ActiveSession? _sessionToRevoke;
    private string _currentSessionId = "session-1";

    // Appearance
    private AppearanceSettings? _appearance;
    private AppearanceEdit? _editAppearance;
    private string? _appearanceSaveMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadProfile();
        await LoadNotifications();
        await LoadSecurity();
        await LoadAppearance();
    }

    // --- Profile ---

    private async Task LoadProfile()
    {
        _profile = await SettingsService.GetProfileAsync();
        _editProfile = new ProfileEdit
        {
            DisplayName = _profile.DisplayName,
            Email = _profile.Email,
            AvatarUrl = _profile.AvatarUrl,
            Bio = _profile.Bio
        };
    }

    private async Task SaveProfile()
    {
        var updated = new UserProfile(_editProfile!.DisplayName, _editProfile.Email, _editProfile.AvatarUrl, _editProfile.Bio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        _profileSaveMessage = "Profile saved successfully!";
        _ = ClearMessageAfterDelay(() => _profileSaveMessage = null);
    }

    private void DiscardProfileChanges()
    {
        _editProfile = new ProfileEdit
        {
            DisplayName = _profile!.DisplayName,
            Email = _profile.Email,
            AvatarUrl = _profile.AvatarUrl,
            Bio = _profile.Bio
        };
        _profileSaveMessage = null;
    }

    // --- Notifications ---

    private async Task LoadNotifications()
    {
        _notificationPrefs = await SettingsService.GetNotificationPrefsAsync();
        _editNotifications = new NotificationEdit
        {
            EmailNotifications = _notificationPrefs.EmailNotifications,
            PushNotifications = _notificationPrefs.PushNotifications,
            WeeklyDigest = _notificationPrefs.WeeklyDigest,
            MutedChannels = new List<string>(_notificationPrefs.MutedChannels)
        };
        // All channels start as muted (checked)
        _mutedChannelStates = _editNotifications.MutedChannels.Select(_ => true).ToList();
    }

    private void ToggleMutedChannel(int index, bool isMuted)
    {
        _mutedChannelStates[index] = isMuted;
    }

    private async Task SaveNotifications()
    {
        var activeMuted = new List<string>();
        for (int i = 0; i < _editNotifications!.MutedChannels.Count; i++)
        {
            if (_mutedChannelStates[i])
                activeMuted.Add(_editNotifications.MutedChannels[i]);
        }
        var prefs = new NotificationPrefs(
            _editNotifications.EmailNotifications,
            _editNotifications.PushNotifications,
            _editNotifications.WeeklyDigest,
            activeMuted);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
        _notificationSaveMessage = "Notification preferences saved!";
        _ = ClearMessageAfterDelay(() => _notificationSaveMessage = null);
    }

    // --- Security ---

    private async Task LoadSecurity()
    {
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _securitySettings.TwoFactorEnabled;
    }

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(_newPassword) || _newPassword != _confirmPassword)
        {
            _passwordMessage = "Passwords do not match or are empty.";
            _passwordMessageIsError = true;
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _passwordMessage = "Password updated successfully!";
        _passwordMessageIsError = false;
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        await LoadSecurity();
        _ = ClearMessageAfterDelay(() => _passwordMessage = null);
    }

    private void PromptRevokeSession(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task ConfirmRevoke()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
            await LoadSecurity();
        }
    }

    // --- Appearance ---

    private async Task LoadAppearance()
    {
        _appearance = await SettingsService.GetAppearanceAsync();
        _editAppearance = new AppearanceEdit
        {
            Theme = _appearance.Theme,
            FontSize = _appearance.FontSize,
            Language = _appearance.Language,
            CompactMode = _appearance.CompactMode
        };
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_editAppearance!.Theme, _editAppearance.FontSize, _editAppearance.Language, _editAppearance.CompactMode);
        await SettingsService.SaveAppearanceAsync(settings);
        _appearance = settings;
        _appearanceSaveMessage = "Appearance settings saved!";
        _ = ClearMessageAfterDelay(() => _appearanceSaveMessage = null);
    }

    private string GetPreviewClasses()
    {
        var classes = new List<string>();
        classes.Add($"preview-theme-{_editAppearance!.Theme.ToLowerInvariant()}");
        classes.Add($"preview-font-{_editAppearance.FontSize.ToLowerInvariant()}");
        if (_editAppearance.CompactMode) classes.Add("preview-compact");
        return string.Join(" ", classes);
    }

    // --- Helpers ---

    private async Task ClearMessageAfterDelay(Action clear)
    {
        await Task.Delay(3000);
        clear();
        await InvokeAsync(StateHasChanged);
    }

    // --- Edit models ---

    private class ProfileEdit
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";
    }

    private class NotificationEdit
    {
        public bool EmailNotifications { get; set; }
        public bool PushNotifications { get; set; }
        public bool WeeklyDigest { get; set; }
        public List<string> MutedChannels { get; set; } = new();
    }

    private class AppearanceEdit
    {
        public string Theme { get; set; } = "";
        public string FontSize { get; set; } = "";
        public string Language { get; set; } = "";
        public bool CompactMode { get; set; }
    }
}
