+}
+
+.avatar-img {
+    width: 100px;
+    height: 100px;
+    border-radius: 50%;
+    object-fit: cover;
+    border: 3px solid #dee2e6;
+}
+
+/* Appearance preview */
+.appearance-preview {
+    border: 1px solid #dee2e6;
+    border-radius: 8px;
+    padding: 1.5rem;
+    transition: all 0.2s ease;
+}
+
+.preview-header {
+    font-weight: 600;
+    margin-bottom: 0.75rem;
+}
+
+.preview-button {
+    padding: 0.4rem 1rem;
+    border-radius: 4px;
+    border: 1px solid #0d6efd;
+    background-color: #0d6efd;
+    color: white;
+    cursor: default;
+}
+
+/* Theme variants */
+.preview-theme-light {
+    background-color: #ffffff;
+    color: #212529;
+}
+
+.preview-theme-dark {
+    background-color: #1a1a2e;
+    color: #e0e0e0;
+    border-color: #444;
+}
+
+.preview-theme-dark .preview-button {
+    background-color: #4a9eff;
+    border-color: #4a9eff;
+}
+
+.preview-theme-system {
+    background-color: #f5f5f5;
+    color: #333;
+}
+
+/* Font size variants */
+.preview-font-small {
+    font-size: 0.8rem;
+}
+
+.preview-font-medium {
+    font-size: 1rem;
+}
+
+.preview-font-large {
+    font-size: 1.25rem;
+}
+
+/* Compact mode */
+.preview-compact {
+    padding: 0.75rem;
+    line-height: 1.2;
+}
+
+.preview-compact .preview-header {
+    margin-bottom: 0.4rem;
+}
+
+.preview-compact .preview-text {
+    margin-bottom: 0.4rem;
+}
+
